/**
 * Project-level AOT pipeline behind `dejavu generate`.
 *
 * Responsibilities, in execution order:
 *   1. snapshot template roots into a `Catalog` (`buildCatalog`)
 *   2. AOT-compile every configured entry against that catalog
 *   3. map the in-memory modules to a deterministic disk layout
 *      (`planOutput`) — declarations, barrel, source maps, manifest
 *   4. publish (`writeOutput`) or compare without writing (`checkOutput`)
 *
 * The output directory is owned by this generator: files are only replaced or
 * removed when the previous manifest records them and their content hash is
 * unchanged. Directories are never cleared recursively.
 */

import { createHash } from "node:crypto";
import {
    existsSync,
    mkdirSync,
    readFileSync,
    readdirSync,
    renameSync,
    rmdirSync,
    rmSync,
    statSync,
    unlinkSync,
    watch as fsWatch,
    writeFileSync,
} from "node:fs";
import type { FSWatcher } from "node:fs";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

import { isEsmScope, loadConfig, resolveConfigPath } from "./config-load.js";
import type { ResolvedConfig } from "./config-load.js";
import { DejavuError } from "./errors.js";
import { precompileCatalog } from "./index.js";
import type { Catalog, Diagnostic, GeneratedOrigin, PrecompileModule } from "./types.js";

/** Runtime package generated modules depend on. */
const RUNTIME_IMPORT = "@doki-land/dejavu-engine/runtime";

/** Manifest contract identity. */
const MANIFEST_CONTRACT = "dejavu.generate/v0";

/** Suffix used for in-directory atomic writes. */
const TMP_SUFFIX = ".dejavu-tmp";

/** Prefix of the staging/backup directory used by one publish transaction. */
const TRANSACTION_PREFIX = ".dejavu-tx-";

/** Fixed, exclusive writer lock inside the output directory. */
const LOCK_FILE = ".dejavu.lock";

/** Fixed record of the in-flight publish transaction. */
const TRANSACTION_RECORD = ".dejavu-transaction.json";

/** Contract identity of the lock and transaction records. */
const LOCK_CONTRACT = "dejavu.generate.lock/v0";
const TRANSACTION_CONTRACT = "dejavu.generate.tx/v0";

/**
 * A lock older than this is treated as abandoned even if its pid is still
 * alive, so a pid that was reused by an unrelated process cannot block the
 * output directory forever.
 */
const LOCK_STALE_MS = 30 * 60 * 1000;

const HEADER = "// Generated by dejavu generate. Do not edit.\n";

// ---------------------------------------------------------------------------
// Public result shapes
// ---------------------------------------------------------------------------

/** One file to publish, keyed by its POSIX path relative to the output dir. */
export type GeneratedFile = {
    path: string;
    content: string;
};

/** Source snapshot recorded by the manifest. */
export type ManifestSource = {
    /** Canonical template id (`root:path`). */
    id: string;
    /** `sha256:<hex>` of the template source. */
    hash: string;
};

/** Content-addressed list of generated files (manifest.json excluded). */
export type ManifestFile = {
    path: string;
    hash: string;
};

/** `manifest.json` payload. Contains no absolute paths or volatile values. */
export type GenerateManifest = {
    contract: string;
    runtime: { import: string; fingerprint: string };
    codegen: { contract: string; fingerprint: string };
    config: {
        fingerprint: string;
        extensions: string[];
        strictUndefined: boolean;
        roots: Array<{ name: string; dir: string; priority: number }>;
    };
    entries: Record<string, string>;
    sources: ManifestSource[];
    files: ManifestFile[];
};

/** Full, in-memory generation result. */
export type GeneratePlan = {
    config: ResolvedConfig;
    /** Absolute output directory. */
    outDir: string;
    /** Files to publish, sorted by path. `manifest.json` is appended at publish time. */
    files: GeneratedFile[];
    manifest: GenerateManifest;
    /** Serialized `manifest.json` including its trailing newline. */
    manifestSource: string;
    /** Non-error diagnostics collected while compiling entries. */
    warnings: Diagnostic[];
};

/** One compiled entry. */
export type CompiledEntry = {
    name: string;
    canonicalId: string;
    modules: PrecompileModule[];
    /** Rust catalog manifest (canonical id → module path). */
    manifestJson: string;
};

/** Aggregated compile output accepted by {@link planOutput}. */
export type GenerateCompilation = {
    catalog: Catalog;
    entries: CompiledEntry[];
    /** Non-error diagnostics collected while compiling entries. */
    warnings: Diagnostic[];
};

/** Options shared by the generate entry points. */
export type BuildGenerateOptions = {
    /** Explicit `--config` value. */
    config?: string;
    /** Directory used for config discovery. Defaults to `process.cwd()`. */
    cwd?: string;
};

/** Drift categories reported by {@link checkOutput}. */
export type DriftKind =
    | "missing"
    | "changed"
    | "stale"
    | "unowned-file"
    | "invalid-manifest"
    | "not-a-directory";

/** One mismatch between the planned output and the contents on disk. */
export type Drift = {
    path: string;
    kind: DriftKind;
};

// ---------------------------------------------------------------------------
// Pipeline entry points
// ---------------------------------------------------------------------------

/** Discover config, snapshot templates, compile every entry, and plan output. */
export async function buildGeneratePlan(
    options: BuildGenerateOptions = {},
): Promise<GeneratePlan> {
    const configFile = resolveConfigPath(options);
    const config = await loadConfig(configFile);
    const catalog = buildCatalog(config);
    const compilation = compileEntries(config, catalog);
    const plan = planOutput(config, compilation);
    warnOnCommonJsOutputScope(plan);
    return plan;
}

/**
 * Generated modules are ESM but keep the documented `.js` names, so a nearest
 * `package.json` without `"type": "module"` makes Node read them as CommonJS.
 * That is a project-side scope problem, not a generation failure: report it as
 * a warning instead of silently producing files the project cannot `import`.
 */
function warnOnCommonJsOutputScope(plan: GeneratePlan): void {
    if (isEsmScope(join(plan.outDir, "index.js"))) return;
    plan.warnings.push({
        code: "dejavu.generate.commonjs-scope",
        severity: "warning",
        stage: "config",
        message:
            `generated ESM modules in ${plan.outDir} sit inside a CommonJS package scope ` +
            '(no "type": "module" in the nearest package.json), so Node reads `.js` there as CommonJS. ' +
            'Add "type": "module" to that package.json or consume the output from an ESM build.',
        argsJson: JSON.stringify({ outDir: plan.outDir }),
        related: [],
    });
}

/**
 * Snapshot every configured root into a catalog.
 *
 * Paths are canonicalized to POSIX and sorted, so the resulting catalog (and
 * every artifact derived from it) is byte-stable for the same inputs.
 */
export function buildCatalog(config: ResolvedConfig): Catalog {
    const roots = config.roots.map((root) => {
        const files: Record<string, string> = {};
        for (const path of scanRoot(root.dir, config.extensions)) {
            try {
                files[path] = readFileSync(join(root.dir, ...path.split("/")), "utf8");
            } catch (error) {
                throw generateError(
                    "dejavu.generate.read-failed",
                    `cannot read template ${root.name}:${path}: ${errorText(error)}`,
                    join(root.dir, path),
                    "load",
                );
            }
        }
        return { name: root.name, scheme: root.name, priority: root.priority, files };
    });

    return { roots, extensions: config.extensions };
}

/** Compile every configured entry against the catalog. */
function compileEntries(config: ResolvedConfig, catalog: Catalog): GenerateCompilation {
    const entryNames = Object.keys(config.generate.entries).sort();
    const entries: CompiledEntry[] = [];
    const warnings: Diagnostic[] = [];

    for (const name of entryNames) {
        const canonicalId = config.generate.entries[name] ?? "";
        assertEntryExists(catalog, name, canonicalId);

        const result = precompileCatalog(catalog, {
            entryId: canonicalId,
            strictUndefined: config.render.strictUndefined,
        });

        const error = DejavuError.fromDiagnostics(result.diagnostics);
        if (error) throw error;
        if (result.modules.length === 0) {
            throw generateError(
                "dejavu.generate.no-modules",
                `entry ${JSON.stringify(name)} produced no modules`,
                undefined,
                "compile",
            );
        }

        for (const diagnostic of result.diagnostics) {
            if (diagnostic.severity !== "error") warnings.push(diagnostic);
        }

        entries.push({
            name,
            canonicalId,
            modules: result.modules,
            manifestJson: result.manifest,
        });
    }

    return { catalog, entries, warnings };
}

/** Map compiled modules onto the public output layout. */
export function planOutput(config: ResolvedConfig, compilation: GenerateCompilation): GeneratePlan {
    const modules = new Map<
        string,
        { code: string; sourceId: string; origins: GeneratedOrigin[] }
    >();
    const codegenContracts = new Set<string>();
    const sources = new Map<string, string>();
    for (const root of compilation.catalog.roots) {
        for (const [path, text] of Object.entries(root.files)) {
            sources.set(`${root.name}:${path}`, text);
        }
    }

    for (const entry of [...compilation.entries].sort((a, b) => compare(a.name, b.name))) {
        if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(entry.name)) {
            throw generateError(
                "dejavu.generate.invalid-entry-name",
                `entry name ${JSON.stringify(entry.name)} is not a valid JavaScript identifier`,
            );
        }

        const idToPath = readCatalogManifest(entry.manifestJson);
        const codegenContract = idToPath.contract;
        codegenContracts.add(codegenContract);

        for (const module of entry.modules) {
            const finalPath = module.path === "index.js" ? `${entry.name}.js` : module.path;
            assertSafeOutputPath(finalPath);
            const sourceId =
                findIdByPath(idToPath.paths, module.path) ??
                // The entry module path is always `index.js` before renaming.
                (module.path === "index.js" ? entry.canonicalId : undefined);
            if (!sourceId) {
                throw generateError(
                    "dejavu.generate.module-unmapped",
                    `codegen returned module ${JSON.stringify(module.path)} without a canonical id`,
                    undefined,
                    "compile",
                );
            }

            const existing = modules.get(finalPath);
            if (existing) {
                if (existing.code !== module.code || existing.sourceId !== sourceId) {
                    throw generateError(
                        "dejavu.generate.module-conflict",
                        `module ${JSON.stringify(finalPath)} was produced twice with different contents`,
                        undefined,
                        "compile",
                    );
                }
                continue;
            }
            modules.set(finalPath, {
                code: module.code,
                sourceId,
                origins: module.origins,
            });
        }
    }

    if (codegenContracts.size !== 1) {
        throw generateError(
            "dejavu.generate.codegen-contract-mismatch",
            `codegen reported mixed catalog contracts: ${[...codegenContracts].sort().join(", ")}`,
            undefined,
            "compile",
        );
    }
    const codegenContract = [...codegenContracts][0] ?? "";

    linkDependencyBindings(modules);

    const entryNames = compilation.entries.map((entry) => entry.name).sort();
    const files: GeneratedFile[] = [];

    for (const [path, module] of [...modules.entries()].sort((a, b) => compare(a[0], b[0]))) {
        const file = posix.basename(path);
        const mapPath = `${path}.map`;
        files.push({
            path,
            content: `${module.code}${sourceMapComment(posix.basename(mapPath))}`,
        });
        files.push({
            path: mapPath,
            content: sourceMapJson(file, module.sourceId, sourceTemplate(module.sourceId, sources), module.origins),
        });
    }

    for (const name of entryNames) {
        files.push({ path: `${name}.d.ts`, content: declarationSource() });
    }

    files.push({ path: "index.js", content: barrelSource(entryNames) });
    files.push({ path: "index.d.ts", content: barrelDeclaration(entryNames) });

    files.sort((a, b) => compare(a.path, b.path));

    const manifest = buildManifest(config, compilation, codegenContract, files);
    const manifestSource = `${JSON.stringify(manifest, null, 2)}\n`;

    return {
        config,
        outDir: config.generate.outDir,
        files,
        manifest,
        manifestSource,
        warnings: compilation.warnings,
    };
}

// ---------------------------------------------------------------------------
// Publishing
// ---------------------------------------------------------------------------

/**
 * Publish a plan into the generator-owned output directory.
 *
 * Ownership rules: an existing non-empty directory without a valid manifest is
 * refused, recorded files whose content no longer matches the recorded hash are
 * refused, and unrecorded files are never deleted. All three checks run before
 * the first write. Stale files are moved one by one — the directory itself is
 * never cleared.
 *
 * A fixed lock file inside the output directory makes it single-writer. The
 * lock is created atomically (`wx`) and released on every exit path, including
 * exceptions. A stale lock (dead pid or clearly expired) is taken over, but
 * only together with the recovery pass below.
 *
 * Publishing is a directory-level transaction. A journal written before the
 * commit records the pre-commit file set; an interrupted run is rolled back by
 * the next invocation before it checks ownership or writes anything new. New
 * contents are staged inside the output directory (same volume, so commit
 * renames stay atomic), originals that must be replaced or removed are moved to
 * a backup area, and `manifest.json` is replaced last.
 */
export function writeOutput(plan: GeneratePlan, outDir: string = plan.outDir): void {
    const dir = resolve(outDir);
    const lock = acquireLock(dir, plan);
    let failed = false;
    try {
        // Recovery precedes the ownership check: a crashed publish leaves a
        // mixture of old and new bytes that the ownership rules would reject.
        recoverInterruptedTransaction(dir, plan);
        publishPlan(plan, dir);
    } catch (error) {
        failed = true;
        throw error;
    } finally {
        lock.release();
        if (failed) removeCreatedDirectories(lock.createdDirs);
    }
}

function publishPlan(plan: GeneratePlan, dir: string): void {
    const state = inspectOutput(dir);

    const planned = new Map(plan.files.map((file) => [file.path, file.content]));
    const owned = new Map((state.manifest?.files ?? []).map((file) => [file.path, file.hash]));

    if (!state.manifest && state.files.length > 0) {
        throw generateError(
            "dejavu.generate.unowned-output",
            `output directory ${dir} is not empty and has no ${MANIFEST_CONTRACT} manifest`,
            dir,
        );
    }

    const stale: string[] = [];
    for (const existing of state.files) {
        if (existing === "manifest.json") continue;
        if (!owned.has(existing)) {
            throw generateError(
                "dejavu.generate.unowned-file",
                `output directory ${dir} contains unrecorded file ${JSON.stringify(existing)}`,
                joinRelative(dir, existing),
            );
        }
        const actual = hashFile(joinRelative(dir, existing));
        if (actual !== owned.get(existing)) {
            throw generateError(
                "dejavu.generate.modified-output",
                `generated file ${JSON.stringify(existing)} was modified outside the generator`,
                joinRelative(dir, existing),
            );
        }
        if (!planned.has(existing)) stale.push(existing);
    }

    const tx = beginTransaction(dir);
    // Snapshot the exact pre-commit file set so a crash between the journal
    // write and the final manifest rename can be undone by a later process.
    const record: TransactionRecord = {
        contract: TRANSACTION_CONTRACT,
        phase: "commit",
        pid: process.pid,
        startedAt: new Date().toISOString(),
        version: generatorVersion(),
        stageDir: relativePosix(dir, tx.stageDir),
        backupDir: relativePosix(dir, tx.backupDir),
        manifestPath: "manifest.json",
        before: state.files.map((path) => ({ path, hash: hashFile(joinRelative(dir, path)) })),
        planned: [...plan.files.map((file) => file.path), "manifest.json"],
        createdDirs: projectedCreatedDirs(dir, plan.files),
    };
    try {
        // Stage every byte we intend to publish before touching the output.
        for (const file of plan.files) {
            const staged = joinRelative(tx.stageDir, file.path);
            mkdirSync(dirname(staged), { recursive: true });
            writeFileSync(staged, file.content, "utf8");
        }
        writeFileSync(join(tx.stageDir, "manifest.json"), plan.manifestSource, "utf8");

        // The journal exists for exactly as long as the commit is in flight.
        writeTransactionRecord(dir, record);

        // Commit step 1: remove stale files by moving them into the backup
        // area, so rollback can restore their exact bytes.
        for (const path of [...stale].sort(compare)) {
            backupFile(dir, tx.backupDir, path, tx.backedUp);
        }

        // Commit step 2: replace or add every planned content file.
        for (const file of plan.files) {
            const target = joinRelative(dir, file.path);
            if (existsSync(target)) {
                if (!isFile(target)) {
                    throw generateError(
                        "dejavu.generate.output-path-conflict",
                        `cannot publish ${JSON.stringify(file.path)}: ${target} is not a regular file`,
                        target,
                    );
                }
                if (readFileText(target) === file.content) continue;
                backupFile(dir, tx.backupDir, file.path, tx.backedUp);
            }
            ensureDirectory(dirname(target), dir, tx.createdDirs);
            renameSync(joinRelative(tx.stageDir, file.path), target);
            tx.placed.push(file.path);
        }

        // Commit step 3: the manifest is the commit marker, so it is only
        // replaced after every content file is in place.
        const manifestTarget = join(dir, "manifest.json");
        const stagedManifest = join(tx.stageDir, "manifest.json");
        if (existsSync(manifestTarget)) {
            if (!isFile(manifestTarget)) {
                throw generateError(
                    "dejavu.generate.output-path-conflict",
                    `cannot publish "manifest.json": ${manifestTarget} is not a regular file`,
                    manifestTarget,
                );
            }
            if (readFileText(manifestTarget) !== plan.manifestSource) {
                backupFile(dir, tx.backupDir, "manifest.json", tx.backedUp);
                renameSync(stagedManifest, manifestTarget);
                tx.placed.push("manifest.json");
            }
        } else {
            renameSync(stagedManifest, manifestTarget);
            tx.placed.push("manifest.json");
        }

        // Mark the commit complete before dropping the journal, so a crash
        // while cleaning up cannot roll a finished publish back.
        record.phase = "committed";
        writeTransactionRecord(dir, record);
        removeTransactionRecord(dir);
        cleanupTransaction(tx.root);
    } catch (error) {
        // Restore files first (their backups live under the transaction root).
        // If that fails, keep the journal and backups so the next run can retry
        // recovery instead of losing the previous output.
        const restored = rollbackTransaction(dir, tx.backupDir, tx.placed, tx.backedUp);
        if (restored) {
            removeTransactionRecord(dir);
            cleanupTransaction(tx.root);
            removeCreatedDirectories(tx.createdDirs);
        }
        throw error;
    }
}

// ---------------------------------------------------------------------------
// Writer lock
// ---------------------------------------------------------------------------

/** Contents of the output-directory lock file. */
type LockRecord = {
    contract: string;
    pid: number;
    startedAt: string;
    version: string;
};

/** An acquired writer lock and the directories acquired along with it. */
type PublishLock = {
    /** Output directories created only to take the lock; removed on failure. */
    createdDirs: string[];
    release(): void;
};

/**
 * Take the exclusive writer lock inside `dir`.
 *
 * An active lock fails immediately: the generator never waits or overwrites.
 * A stale lock (unreadable record, dead pid, or older than {@link LOCK_STALE_MS})
 * is reported as a warning and taken over, and then the caller still runs
 * transaction recovery first.
 */
function acquireLock(dir: string, plan: GeneratePlan): PublishLock {
    if (existsSync(dir) && !isDirectory(dir)) {
        throw generateError(
            "dejavu.generate.output-not-directory",
            `output path ${dir} is not a directory`,
            dir,
        );
    }

    const createdDirs: string[] = [];
    ensureDirectory(dir, dir, createdDirs);
    const lockPath = join(dir, LOCK_FILE);
    const record: LockRecord = {
        contract: LOCK_CONTRACT,
        pid: process.pid,
        startedAt: new Date().toISOString(),
        version: generatorVersion(),
    };
    const source = `${JSON.stringify(record, null, 2)}\n`;

    let locked = false;
    try {
        for (let attempt = 0; attempt < 3; attempt += 1) {
            try {
                writeFileSync(lockPath, source, { encoding: "utf8", flag: "wx" });
                locked = true;
                return { createdDirs, release: () => releaseLock(lockPath, record) };
            } catch (error) {
                if (errnoCode(error) !== "EEXIST") {
                    throw generateError(
                        "dejavu.generate.lock-failed",
                        `cannot create the output lock ${lockPath}: ${errorText(error)}`,
                        lockPath,
                        "publish",
                    );
                }
            }

            const existing = readLockRecord(lockPath);
            const stale = staleLockReason(existing);
            if (stale === undefined) {
                const owner = existing
                    ? `pid ${existing.pid}, started ${existing.startedAt}`
                    : "an unreadable lock file";
                throw generateError(
                    "dejavu.generate.output-locked",
                    `output directory ${dir} is locked by an active dejavu generate run (${owner}); wait for it to finish`,
                    lockPath,
                    "publish",
                );
            }

            plan.warnings.push({
                code: "dejavu.generate.stale-lock",
                severity: "warning",
                stage: "publish",
                message: `taking over a stale lock in ${dir}: ${stale}`,
                argsJson: JSON.stringify({ lock: lockPath, pid: existing?.pid ?? null }),
                related: [],
            });

            try {
                unlinkSync(lockPath);
            } catch (error) {
                if (errnoCode(error) !== "ENOENT") {
                    throw generateError(
                        "dejavu.generate.lock-failed",
                        `cannot remove the stale output lock ${lockPath}: ${errorText(error)}`,
                        lockPath,
                        "publish",
                    );
                }
            }
            // Retry the exclusive create; losing a race twice means another
            // writer already owns the directory again.
        }

        throw generateError(
            "dejavu.generate.output-locked",
            `output directory ${dir} is locked by another dejavu generate run`,
            join(dir, LOCK_FILE),
            "publish",
        );
    } finally {
        // A failed acquisition must not leave behind an empty output directory
        // that this run created.
        if (!locked) removeCreatedDirectories(createdDirs);
    }
}

function readLockRecord(path: string): LockRecord | undefined {
    try {
        const record = asRecord(JSON.parse(readFileText(path)));
        if (
            !record ||
            typeof record.contract !== "string" ||
            typeof record.pid !== "number" ||
            typeof record.startedAt !== "string"
        ) {
            return undefined;
        }
        return {
            contract: record.contract,
            pid: record.pid,
            startedAt: record.startedAt,
            version: typeof record.version === "string" ? record.version : "",
        };
    } catch {
        return undefined;
    }
}

/** Why an existing lock is stale, or `undefined` while it is still valid. */
function staleLockReason(record: LockRecord | undefined): string | undefined {
    if (!record) return "the lock record is unreadable or incomplete";
    if (record.contract !== LOCK_CONTRACT) return "the lock record has an unknown contract";
    if (!Number.isInteger(record.pid) || record.pid <= 0) return "the lock record has no valid pid";

    const started = Date.parse(record.startedAt);
    if (Number.isNaN(started)) return "the lock record has no valid start time";
    if (Date.now() - started > LOCK_STALE_MS) {
        return `pid ${record.pid} started at ${record.startedAt}, which is older than ${LOCK_STALE_MS / 60000} minutes`;
    }
    if (!isProcessAlive(record.pid)) return `pid ${record.pid} is no longer running`;
    return undefined;
}

function isProcessAlive(pid: number): boolean {
    try {
        process.kill(pid, 0);
        return true;
    } catch (error) {
        // EPERM means the pid exists but belongs to another user.
        return errnoCode(error) === "EPERM";
    }
}

/** Remove the lock only if it is still the lock this run created. */
function releaseLock(lockPath: string, record: LockRecord): void {
    try {
        const current = readLockRecord(lockPath);
        if (!current || current.pid !== record.pid || current.startedAt !== record.startedAt) return;
        unlinkSync(lockPath);
    } catch {
        // Releasing must never mask the publish result.
    }
}

// ---------------------------------------------------------------------------
// Persistent transaction journal / crash recovery
// ---------------------------------------------------------------------------

/** Persisted state of one publish commit. */
type TransactionRecord = {
    contract: string;
    phase: "commit" | "committed";
    pid: number;
    startedAt: string;
    version: string;
    /** POSIX-relative staging directory inside the output directory. */
    stageDir: string;
    /** POSIX-relative backup directory inside the output directory. */
    backupDir: string;
    /** POSIX-relative manifest path. */
    manifestPath: string;
    /** Every file present before the commit, with its content hash. */
    before: Array<{ path: string; hash: string }>;
    /** Every file this commit may place, so recovery never deletes user files. */
    planned: string[];
    /** Output directories the commit may create; pruned again on recovery. */
    createdDirs: string[];
};

function writeTransactionRecord(dir: string, record: TransactionRecord): void {
    const target = join(dir, TRANSACTION_RECORD);
    const temp = `${target}${TMP_SUFFIX}`;
    writeFileSync(temp, `${JSON.stringify(record, null, 2)}\n`, "utf8");
    renameSync(temp, target);
}

function removeTransactionRecord(dir: string): void {
    for (const path of [join(dir, TRANSACTION_RECORD), join(dir, `${TRANSACTION_RECORD}${TMP_SUFFIX}`)]) {
        try {
            unlinkSync(path);
        } catch {
            // Already gone.
        }
    }
}

/**
 * Read and validate a leftover journal. A malformed record stops generation:
 * silently deleting its backup area could destroy the previous output.
 */
function readTransactionRecord(dir: string): TransactionRecord {
    const recordPath = join(dir, TRANSACTION_RECORD);
    let parsed: unknown;
    try {
        parsed = JSON.parse(readFileText(recordPath));
    } catch (error) {
        throw generateError(
            "dejavu.generate.transaction-record-invalid",
            `${recordPath} is not valid JSON: ${errorText(error)}`,
            recordPath,
            "publish",
        );
    }

    const record = asRecord(parsed);
    if (
        !record ||
        record.contract !== TRANSACTION_CONTRACT ||
        (record.phase !== "commit" && record.phase !== "committed") ||
        typeof record.stageDir !== "string" ||
        typeof record.backupDir !== "string" ||
        typeof record.manifestPath !== "string" ||
        !Array.isArray(record.before) ||
        !Array.isArray(record.planned) ||
        !Array.isArray(record.createdDirs)
    ) {
        throw generateError(
            "dejavu.generate.transaction-record-invalid",
            `${recordPath} does not carry a valid ${TRANSACTION_CONTRACT} transaction record`,
            recordPath,
            "publish",
        );
    }

    const phase = record.phase as "commit" | "committed";
    const stageDir = record.stageDir as string;
    const backupDir = record.backupDir as string;
    const manifestPath = record.manifestPath as string;

    const before: Array<{ path: string; hash: string }> = [];
    for (const item of record.before) {
        const entry = asRecord(item);
        if (!entry || typeof entry.path !== "string" || typeof entry.hash !== "string") {
            throw invalidRecord(recordPath, "a malformed `before` entry");
        }
        assertRecordPath(entry.path, recordPath);
        before.push({ path: entry.path, hash: entry.hash });
    }

    const createdDirs: string[] = [];
    for (const item of record.createdDirs) {
        if (typeof item !== "string") throw invalidRecord(recordPath, "a malformed `createdDirs` entry");
        assertRecordPath(item, recordPath);
        createdDirs.push(item);
    }

    const planned: string[] = [];
    for (const item of record.planned) {
        if (typeof item !== "string") throw invalidRecord(recordPath, "a malformed `planned` entry");
        assertRecordPath(item, recordPath);
        planned.push(item);
    }

    assertRecordPath(stageDir, recordPath);
    assertRecordPath(backupDir, recordPath);
    assertRecordPath(manifestPath, recordPath);

    const stageRoot = posix.dirname(stageDir);
    const backupRoot = posix.dirname(backupDir);
    if (
        stageRoot !== backupRoot ||
        posix.basename(stageRoot) !== stageRoot ||
        !stageRoot.startsWith(TRANSACTION_PREFIX)
    ) {
        throw invalidRecord(recordPath, "staging and backup directories outside one transaction root");
    }

    return {
        contract: TRANSACTION_CONTRACT,
        phase,
        pid: typeof record.pid === "number" ? record.pid : 0,
        startedAt: typeof record.startedAt === "string" ? record.startedAt : "",
        version: typeof record.version === "string" ? record.version : "",
        stageDir,
        backupDir,
        manifestPath,
        before,
        planned,
        createdDirs,
    };
}

/**
 * Roll a leftover transaction back to the recorded pre-commit state, then
 * remove its journal and staging/backup directory. Failures stop generation and
 * keep both artifacts so the recovery can be retried.
 */
function recoverInterruptedTransaction(dir: string, plan: GeneratePlan): void {
    const recordPath = join(dir, TRANSACTION_RECORD);
    if (!existsSync(recordPath)) return;

    const record = readTransactionRecord(dir);
    const root = joinRelative(dir, posix.dirname(record.stageDir));

    if (record.phase === "committed") {
        // The publish finished; only the cleanup did not.
        cleanupTransaction(root);
        removeTransactionRecord(dir);
        return;
    }

    try {
        restoreBackedUpFiles(dir, record);
        removeFilesOutsideSnapshot(dir, record);
        removeCreatedDirectories(record.createdDirs.map((path) => joinRelative(dir, path)));
        assertRestoredSnapshot(dir, record);
    } catch (error) {
        throw generateError(
            "dejavu.generate.recovery-failed",
            `cannot restore the previous output in ${dir}; ` +
                `${recordPath} and its backup area were kept: ${errorText(error)}`,
            recordPath,
            "publish",
        );
    }

    cleanupTransaction(root);
    removeTransactionRecord(dir);
    plan.warnings.push({
        code: "dejavu.generate.recovered",
        severity: "warning",
        stage: "publish",
        message: `rolled back an interrupted publish in ${dir} before generating`,
        argsJson: JSON.stringify({ record: recordPath }),
        related: [],
    });
}

function restoreBackedUpFiles(dir: string, record: TransactionRecord): void {
    const backupDir = joinRelative(dir, record.backupDir);
    for (const path of listRelativeFiles(backupDir)) {
        const target = joinRelative(dir, path);
        if (existsSync(target)) {
            if (!isFile(target)) throw new Error(`${target} is not a regular file`);
            unlinkSync(target);
        }
        mkdirSync(dirname(target), { recursive: true });
        renameSync(joinRelative(backupDir, path), target);
    }
}

/**
 * Delete files the interrupted commit placed that were not present before it.
 * Only recorded `planned` paths are removed, so a file the user created while
 * the publish was interrupted is left untouched for the ownership check.
 */
function removeFilesOutsideSnapshot(dir: string, record: TransactionRecord): void {
    const before = new Set(record.before.map((file) => file.path));
    for (const path of record.planned) {
        if (before.has(path)) continue;
        const target = joinRelative(dir, path);
        if (existsSync(target) && isFile(target)) unlinkSync(target);
    }
}

/** Verify that recovery really produced the recorded pre-commit bytes. */
function assertRestoredSnapshot(dir: string, record: TransactionRecord): void {
    const expected = new Set(record.before.map((file) => file.path));
    for (const file of record.before) {
        const target = joinRelative(dir, file.path);
        if (!isFile(target)) throw new Error(`restored file ${JSON.stringify(file.path)} is missing`);
        if (hashFile(target) !== file.hash) {
            throw new Error(`restored file ${JSON.stringify(file.path)} does not match its recorded hash`);
        }
    }
    for (const path of record.planned) {
        if (expected.has(path)) continue;
        if (existsSync(joinRelative(dir, path))) {
            throw new Error(`interrupted publish left ${JSON.stringify(path)} behind`);
        }
    }
}

function invalidRecord(recordPath: string, detail: string): DejavuError {
    return generateError(
        "dejavu.generate.transaction-record-invalid",
        `${recordPath} has ${detail}`,
        recordPath,
        "publish",
    );
}

/** Reject journal paths that could escape the output directory. */
function assertRecordPath(path: string, recordPath: string): void {
    if (
        path === "" ||
        path.startsWith("/") ||
        /^[A-Za-z]:/.test(path) ||
        path.split("/").some((segment) => segment === "" || segment === "." || segment === "..")
    ) {
        throw invalidRecord(recordPath, `an unsafe path ${JSON.stringify(path)}`);
    }
}

/** Directories the planned files will create inside the output directory. */
function projectedCreatedDirs(dir: string, files: GeneratedFile[]): string[] {
    const dirs: string[] = [];
    const seen = new Set<string>();
    for (const file of files) {
        let current = posix.dirname(file.path);
        while (current !== "." && current !== "" && !seen.has(current)) {
            seen.add(current);
            if (existsSync(joinRelative(dir, current))) break;
            dirs.push(current);
            current = posix.dirname(current);
        }
    }
    return dirs;
}

/** One publish transaction's staging and rollback state. */
type PublishTransaction = {
    root: string;
    stageDir: string;
    backupDir: string;
    /** Output-directory children created here; removed again on rollback. */
    createdDirs: string[];
    /** Relative paths whose originals were moved into the backup area. */
    backedUp: string[];
    /** Relative paths whose new bytes were already renamed into place. */
    placed: string[];
};

let transactionSequence = 0;

function beginTransaction(dir: string): PublishTransaction {
    const createdDirs: string[] = [];
    ensureDirectory(dir, dir, createdDirs);
    transactionSequence += 1;
    const root = join(dir, `${TRANSACTION_PREFIX}${process.pid}-${Date.now()}-${transactionSequence}`);
    mkdirSync(root, { recursive: true });
    const stageDir = join(root, "stage");
    const backupDir = join(root, "backup");
    mkdirSync(stageDir, { recursive: true });
    mkdirSync(backupDir, { recursive: true });
    return { root, stageDir, backupDir, createdDirs, backedUp: [], placed: [] };
}

/**
 * Create `target` and its missing ancestors, recording only directories that
 * belong to the output directory so rollback can remove them again.
 */
function ensureDirectory(target: string, root: string, created: string[]): void {
    const missing: string[] = [];
    let current = target;
    while (!existsSync(current)) {
        missing.push(current);
        const parent = dirname(current);
        if (parent === current) break;
        current = parent;
    }
    if (missing.length === 0) return;
    mkdirSync(target, { recursive: true });
    for (const path of missing) {
        if (isWithin(root, path)) created.push(path);
    }
}

/** Move one existing output file aside, preserving its exact bytes. */
function backupFile(dir: string, backupDir: string, path: string, backedUp: string[]): void {
    const destination = joinRelative(backupDir, path);
    mkdirSync(dirname(destination), { recursive: true });
    renameSync(joinRelative(dir, path), destination);
    backedUp.push(path);
}

/**
 * Undo a partially committed transaction. Every step is best-effort and keeps
 * going, so one busy file cannot prevent the remaining originals from coming
 * back. Returns `false` when any file could not be restored; the caller then
 * keeps the journal and backup area for the next run's recovery.
 */
function rollbackTransaction(
    dir: string,
    backupDir: string,
    placed: string[],
    backedUp: string[],
): boolean {
    let restored = true;
    for (const path of [...placed].reverse()) {
        try {
            unlinkSync(joinRelative(dir, path));
        } catch (error) {
            // Already gone is fine; anything else leaves the journal in place.
            if (errnoCode(error) !== "ENOENT") restored = false;
        }
    }
    for (const path of [...backedUp].reverse()) {
        try {
            const target = joinRelative(dir, path);
            mkdirSync(dirname(target), { recursive: true });
            renameSync(joinRelative(backupDir, path), target);
        } catch (error) {
            // ENOENT means the backup was already restored; other failures
            // need the journal to survive.
            if (errnoCode(error) !== "ENOENT") restored = false;
        }
    }
    return restored;
}

function cleanupTransaction(root: string): void {
    try {
        rmSync(root, { recursive: true, force: true });
    } catch {
        // Best-effort cleanup must never mask the publish result.
    }
}

/** Remove output directories that only this transaction created and that are empty again. */
function removeCreatedDirectories(createdDirs: string[]): void {
    for (const path of [...createdDirs].sort((a, b) => b.length - a.length)) {
        try {
            rmdirSync(path);
        } catch {
            // Not empty or already removed: leave it alone.
        }
    }
}

/** Join a POSIX relative output path onto an absolute directory. */
function joinRelative(dir: string, path: string): string {
    return join(dir, ...path.split("/"));
}

function isWithin(root: string, path: string): boolean {
    return path === root || path.startsWith(`${root}${sep}`);
}

/**
 * Compare a plan with the output on disk without writing anything.
 *
 * Missing, changed, stale, unrecorded, and malformed-manifest states are all
 * reported as drift; an empty directory therefore never passes a check for a
 * non-empty plan.
 */
export function checkOutput(plan: GeneratePlan, outDir: string = plan.outDir): Drift[] {
    const dir = resolve(outDir);

    let state: OutputState;
    try {
        state = inspectOutput(dir);
    } catch (error) {
        const kind: DriftKind =
            error instanceof DejavuError && error.code === "dejavu.generate.output-not-directory"
                ? "not-a-directory"
                : "invalid-manifest";
        return [{ path: "manifest.json", kind }];
    }

    const drift: Drift[] = [];
    const planned = new Map(plan.files.map((file) => [file.path, file.content]));
    const owned = new Set((state.manifest?.files ?? []).map((file) => file.path));

    for (const file of plan.files) {
        const target = join(dir, ...file.path.split("/"));
        if (!existsSync(target)) {
            drift.push({ path: file.path, kind: "missing" });
            continue;
        }
        if (readFileText(target) !== file.content) {
            drift.push({ path: file.path, kind: "changed" });
        }
    }

    const manifestPath = join(dir, "manifest.json");
    if (!state.manifest) {
        drift.push({ path: "manifest.json", kind: "missing" });
    } else if (!existsSync(manifestPath) || readFileText(manifestPath) !== plan.manifestSource) {
        drift.push({ path: "manifest.json", kind: "changed" });
    }

    for (const existing of state.files) {
        if (existing === "manifest.json") continue;
        if (!planned.has(existing)) {
            drift.push({ path: existing, kind: owned.has(existing) ? "stale" : "unowned-file" });
        }
    }

    return drift.sort((a, b) => compare(a.path, b.path));
}

// ---------------------------------------------------------------------------
// Watch mode
// ---------------------------------------------------------------------------

/** Output sink used by watch mode. */
export type WatchIO = {
    stdout(text: string): void;
    stderr(text: string): void;
};

/**
 * Run a full generate, then rebuild on template/config changes.
 *
 * A failed rebuild keeps the previous successful output untouched and keeps
 * watching. The returned promise never settles; termination is the host's
 * interrupt handling.
 */
export async function watchGenerate(
    options: BuildGenerateOptions & { io?: WatchIO } = {},
): Promise<number> {
    const io: WatchIO = options.io ?? {
        stdout: (text) => process.stdout.write(text),
        stderr: (text) => process.stderr.write(text),
    };
    const cwd = resolve(options.cwd ?? process.cwd());

    let watchers: FSWatcher[] = [];
    let timer: NodeJS.Timeout | undefined;
    let running = false;
    let pending = false;

    const closeWatchers = (): void => {
        for (const watcher of watchers) {
            try {
                watcher.close();
            } catch {
                // ignore
            }
        }
        watchers = [];
    };

    const install = (plan?: GeneratePlan, configFile?: string): void => {
        closeWatchers();
        const targets = new Set<string>();

        for (const root of plan?.config.roots ?? []) targets.add(root.dir);
        const file = configFile ?? safeResolveConfigPath(options);
        if (file) {
            targets.add(file);
            targets.add(dirname(file));
            for (const dependency of configDependencies(file)) targets.add(dependency);
        } else {
            targets.add(cwd);
        }

        for (const target of targets) {
            try {
                watchers.push(fsWatch(target, { recursive: isDirectory(target) }, () => schedule()));
            } catch {
                // Recursive watch is platform dependent: fall back to one handle
                // per existing directory (new directories re-arm after a rebuild).
                const directories = isDirectory(target) ? listDirectories(target) : [];
                for (const directory of directories) {
                    try {
                        watchers.push(fsWatch(directory, () => schedule()));
                    } catch {
                        // ignore unwatchable directory
                    }
                }
            }
        }
    };

    const rebuild = async (): Promise<void> => {
        try {
            const plan = await buildGeneratePlan(options);
            writeOutput(plan);
            io.stdout(
                `dejavu generate: wrote ${plan.files.length + 1} files to ${displayPath(plan.outDir, cwd)}\n`,
            );
            for (const warning of plan.warnings) {
                io.stderr(`${warning.severity.toUpperCase()} ${warning.code}: ${warning.message}\n`);
            }
            io.stdout("dejavu generate: watching for changes\n");
            install(plan, plan.config.file);
        } catch (error) {
            reportGenerateError(error, io);
            io.stdout("dejavu generate: keeping previous output and watching for changes\n");
            install(undefined);
        }
    };

    const run = (): void => {
        if (running) {
            pending = true;
            return;
        }
        running = true;
        void (async () => {
            do {
                pending = false;
                await rebuild();
            } while (pending);
            running = false;
        })();
    };

    const schedule = (): void => {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            timer = undefined;
            run();
        }, 120);
    };

    await rebuild();

    await new Promise<void>(() => {
        // Never resolves: watch mode terminates on host interrupt.
    });

    return 0;
}

/** Print a generate failure through the CLI-style diagnostic format. */
export function reportGenerateError(error: unknown, io: WatchIO): void {
    if (error instanceof DejavuError) {
        for (const diagnostic of error.diagnostics) {
            const where = diagnostic.path ? ` (${diagnostic.path})` : "";
            io.stderr(
                `${diagnostic.severity.toUpperCase()} ${diagnostic.code}${where}: ${diagnostic.message}\n`,
            );
        }
        return;
    }
    io.stderr(`dejavu generate: ${errorText(error)}\n`);
}

// ---------------------------------------------------------------------------
// Catalog manifest / module linking
// ---------------------------------------------------------------------------

type CatalogManifest = {
    contract: string;
    paths: Record<string, string>;
};

function readCatalogManifest(json: string): CatalogManifest {
    let parsed: unknown;
    try {
        parsed = JSON.parse(json);
    } catch {
        throw generateError(
            "dejavu.generate.manifest-invalid",
            "codegen returned an unreadable catalog manifest",
            undefined,
            "compile",
        );
    }
    const record = asRecord(parsed);
    const format = record?.format;
    const modules = record?.modules;
    if (typeof format !== "string" || !asRecord(modules)) {
        throw generateError(
            "dejavu.generate.manifest-invalid",
            "codegen catalog manifest is missing `format` or `modules`",
            undefined,
            "compile",
        );
    }
    const paths: Record<string, string> = {};
    for (const [id, path] of Object.entries(asRecord(modules) ?? {})) {
        if (typeof path === "string") paths[id] = path;
    }
    return { contract: format, paths };
}

function findIdByPath(paths: Record<string, string>, path: string): string | undefined {
    for (const [id, candidate] of Object.entries(paths)) {
        if (candidate === path) return id;
    }
    return undefined;
}

/**
 * codegen emits `import { __tmpl_<id> } from "./_internal/..."` for `include`
 * dependencies but only exports `render` from each module. Add the missing
 * re-export at the layout boundary so the published bundle is importable.
 * Existing exports are detected and left untouched.
 */
function linkDependencyBindings(modules: Map<string, { code: string; sourceId: string }>): void {
    const additions = new Map<string, Set<string>>();
    const importPattern = /^import \{ ([^}]+) \} from "(\.[^"]+)";$/gm;

    for (const [path, module] of modules) {
        for (const match of module.code.matchAll(importPattern)) {
            const bindings = (match[1] ?? "").split(",").map((part) => part.trim()).filter(Boolean);
            const target = resolveModulePath(path, match[2] ?? "");
            const targetModule = modules.get(target);
            if (!targetModule) continue;
            for (const binding of bindings) {
                if (!binding.startsWith("__tmpl_")) continue;
                const existing = additions.get(target) ?? new Set<string>();
                existing.add(binding);
                additions.set(target, existing);
            }
        }
    }

    for (const [path, bindings] of additions) {
        const module = modules.get(path);
        if (!module) continue;
        const appended = [...bindings]
            .sort(compare)
            .filter((binding) => !hasExport(module.code, binding))
            .map((binding) => `export { render as ${binding} };\n`)
            .join("");
        if (appended) modules.set(path, { ...module, code: `${module.code}${appended}` });
    }
}

function hasExport(code: string, binding: string): boolean {
    return new RegExp(`export (?:const|let|var|function|class) ${binding}\\b`).test(code) ||
        new RegExp(`export \\{[^}]*\\b${binding}\\b`).test(code);
}

function resolveModulePath(fromPath: string, specifier: string): string {
    const joined = posix.normalize(posix.join(posix.dirname(fromPath), specifier));
    return joined.startsWith("./") ? joined.slice(2) : joined;
}

// ---------------------------------------------------------------------------
// Declaration / barrel / source map emitters
// ---------------------------------------------------------------------------

function declarationSource(): string {
    return `${HEADER}export type RenderOptions = {
    strictUndefined?: boolean;
};

export declare function render(ctx?: Record<string, unknown>, options?: RenderOptions): string;
`;
}

function barrelSource(entryNames: string[]): string {
    const lines = entryNames.map((name) => `export { render as ${name} } from "./${name}.js";`);
    return `${HEADER}${lines.join("\n")}\n`;
}

function barrelDeclaration(entryNames: string[]): string {
    const lines = entryNames.map((name) => `export { render as ${name} } from "./${name}.js";`);
    return `${HEADER}${lines.join("\n")}\n`;
}

function sourceMapComment(fileName: string): string {
    return `//# sourceMappingURL=${fileName}\n`;
}

/** Template source text behind a canonical id (needed for `sourcesContent`). */
function sourceTemplate(sourceId: string, sources: Map<string, string>): string {
    const text = sources.get(sourceId);
    if (text === undefined) {
        throw generateError(
            "dejavu.generate.source-missing",
            `generated module references ${JSON.stringify(sourceId)} but the catalog has no source for it`,
            undefined,
            "compile",
        );
    }
    return text;
}

/** Source map v3 with one segment per generated line that starts a construct. */
function sourceMapJson(
    file: string,
    sourceId: string,
    text: string,
    origins: GeneratedOrigin[],
): string {
    return JSON.stringify({
        version: 3,
        file,
        sources: [sourceId],
        sourcesContent: [text],
        names: [],
        mappings: encodeMappings(text, origins),
    });
}

const BASE64_DIGITS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/** Base64 VLQ, the only encoding source maps use for segment fields. */
function encodeVlq(value: number): string {
    let rest = value < 0 ? (-value << 1) | 1 : value << 1;
    let out = "";
    do {
        let digit = rest & 31;
        rest >>>= 5;
        if (rest > 0) digit |= 32;
        out += BASE64_DIGITS[digit];
    } while (rest > 0);
    return out;
}

/** Byte offset of each 0-based line start, plus its JS (UTF-16) offset. */
type LineStart = { byte: number; unit: number };

/**
 * Rust spans are byte offsets while source-map columns count UTF-16 units, so
 * both coordinate systems are tracked side by side.
 */
function lineStarts(text: string): LineStart[] {
    const starts: LineStart[] = [{ byte: 0, unit: 0 }];
    let byte = 0;
    let unit = 0;
    for (const char of text) {
        byte += Buffer.byteLength(char, "utf8");
        unit += char.length;
        if (char === "\n") starts.push({ byte, unit });
    }
    return starts;
}

/** Convert one template byte offset into 0-based line + UTF-16 column. */
function positionAt(text: string, starts: LineStart[], byteOffset: number): { line: number; column: number } {
    const total = starts[starts.length - 1] ?? { byte: 0, unit: 0 };
    const offset = Math.max(0, Math.min(byteOffset, total.byte));
    let low = 0;
    let high = starts.length - 1;
    while (low < high) {
        const mid = (low + high + 1) >> 1;
        if ((starts[mid]?.byte ?? 0) <= offset) low = mid;
        else high = mid - 1;
    }
    const start = starts[low] ?? { byte: 0, unit: 0 };
    const end = starts[low + 1]?.unit ?? text.length;
    const line = text.slice(start.unit, end);
    let bytes = 0;
    let column = 0;
    for (const char of line) {
        const size = Buffer.byteLength(char, "utf8");
        if (bytes + size > offset - start.byte) break;
        bytes += size;
        column += char.length;
    }
    return { line: low, column };
}

/**
 * Build the `mappings` string. Each generated line gets at most one segment at
 * column 0 pointing at the template construct that produced it; fields are
 * delta-encoded against the previous segment, as the format requires.
 */
function encodeMappings(text: string, origins: GeneratedOrigin[]): string {
    if (origins.length === 0) return "";

    const byLine = new Map<number, GeneratedOrigin>();
    for (const origin of origins) {
        if (!byLine.has(origin.line)) byLine.set(origin.line, origin);
    }
    const starts = lineStarts(text);
    const lastLine = Math.max(...byLine.keys());

    const lines: string[] = [];
    let previousLine = 0;
    let previousColumn = 0;

    for (let line = 0; line <= lastLine; line++) {
        const origin = byLine.get(line);
        if (!origin) {
            lines.push("");
            continue;
        }
        const position = positionAt(text, starts, origin.start);
        lines.push(
            [
                encodeVlq(0),
                encodeVlq(0),
                encodeVlq(position.line - previousLine),
                encodeVlq(position.column - previousColumn),
            ].join(""),
        );
        previousLine = position.line;
        previousColumn = position.column;
    }

    return lines.join(";");
}

// ---------------------------------------------------------------------------
// Manifest
// ---------------------------------------------------------------------------

function buildManifest(
    config: ResolvedConfig,
    compilation: GenerateCompilation,
    codegenContract: string,
    files: GeneratedFile[],
): GenerateManifest {
    const entries: Record<string, string> = {};
    for (const name of Object.keys(config.generate.entries).sort(compare)) {
        entries[name] = config.generate.entries[name] ?? "";
    }

    const roots = [...config.roots]
        .sort((a, b) => compare(a.name, b.name))
        .map((root) => ({
            name: root.name,
            dir: relativePosix(config.dir, root.dir),
            priority: root.priority,
        }));

    const configCanonical = JSON.stringify({
        extensions: config.extensions,
        strictUndefined: config.render.strictUndefined,
        roots,
        outDir: relativePosix(config.dir, config.generate.outDir),
        entries,
    });

    const runtimeBindings = collectRuntimeBindings(files.map((file) => file.content));
    const codegenFingerprint = hashText(
        files
            .filter((file) => file.path.endsWith(".js"))
            .map((file) => `${file.path}\n${file.content}`)
            .join("\n"),
    );

    const sources: ManifestSource[] = [];
    for (const root of compilation.catalog.roots) {
        for (const path of Object.keys(root.files).sort(compare)) {
            sources.push({
                id: `${root.name}:${path}`,
                hash: hashText(root.files[path] ?? ""),
            });
        }
    }
    sources.sort((a, b) => compare(a.id, b.id));

    return {
        contract: MANIFEST_CONTRACT,
        runtime: {
            import: RUNTIME_IMPORT,
            fingerprint: hashText(
                `${RUNTIME_IMPORT}\n${runtimeBindings.join(",")}`,
            ),
        },
        codegen: {
            contract: codegenContract,
            fingerprint: codegenFingerprint,
        },
        config: {
            fingerprint: hashText(configCanonical),
            extensions: [...config.extensions],
            strictUndefined: config.render.strictUndefined,
            roots,
        },
        entries,
        sources,
        files: files
            .map((file) => ({ path: file.path, hash: hashText(file.content) }))
            .sort((a, b) => compare(a.path, b.path)),
    };
}

function collectRuntimeBindings(codes: string[]): string[] {
    const names = new Set<string>();
    const pattern = new RegExp(
        `^import \\{ ([^}]+) \\} from "${RUNTIME_IMPORT.replace(/[/\\]/g, "\\$&")}";$`,
        "gm",
    );
    for (const code of codes) {
        for (const match of code.matchAll(pattern)) {
            for (const name of (match[1] ?? "").split(",")) {
                const trimmed = name.trim();
                if (trimmed) names.add(trimmed);
            }
        }
    }
    return [...names].sort(compare);
}

// ---------------------------------------------------------------------------
// Output state / ownership helpers
// ---------------------------------------------------------------------------

type OutputState = {
    manifest?: StoredManifest;
    /** Every file path currently inside the output directory (POSIX relative). */
    files: string[];
};

type StoredManifest = {
    contract: string;
    files: Array<{ path: string; hash: string }>;
};

function inspectOutput(dir: string): OutputState {
    if (!existsSync(dir)) return { files: [] };
    if (!isDirectory(dir)) {
        throw generateError(
            "dejavu.generate.output-not-directory",
            `output path ${dir} is not a directory`,
            dir,
        );
    }

    const manifestPath = join(dir, "manifest.json");
    let manifest: StoredManifest | undefined;
    if (existsSync(manifestPath)) {
        let parsed: unknown;
        try {
            parsed = JSON.parse(readFileText(manifestPath));
        } catch {
            throw generateError(
                "dejavu.generate.manifest-invalid",
                `${manifestPath} is not valid JSON`,
                manifestPath,
            );
        }
        const record = asRecord(parsed);
        if (!record || record.contract !== MANIFEST_CONTRACT || !Array.isArray(record.files)) {
            throw generateError(
                "dejavu.generate.manifest-invalid",
                `${manifestPath} does not carry a ${MANIFEST_CONTRACT} manifest`,
                manifestPath,
            );
        }
        const files: Array<{ path: string; hash: string }> = [];
        for (const item of record.files) {
            const entry = asRecord(item);
            if (!entry || typeof entry.path !== "string" || typeof entry.hash !== "string") {
                throw generateError(
                    "dejavu.generate.manifest-invalid",
                    `${manifestPath} contains a malformed file record`,
                    manifestPath,
                );
            }
            files.push({ path: entry.path, hash: entry.hash });
        }
        manifest = { contract: record.contract, files };
    }

    return { manifest, files: listFiles(dir) };
}

function listFiles(root: string, prefix = ""): string[] {
    const out: string[] = [];
    for (const entry of readdirSync(root, { withFileTypes: true }).sort((a, b) => compare(a.name, b.name))) {
        if (entry.name.startsWith(TRANSACTION_PREFIX)) {
            // Staging/backup area of a running or interrupted publish. It is
            // never generated content and never owned by a manifest.
            continue;
        }
        if (entry.name === LOCK_FILE || entry.name === TRANSACTION_RECORD) {
            // Generator control files, not generated content.
            continue;
        }
        const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
        if (entry.isDirectory()) {
            out.push(...listFiles(join(root, entry.name), rel));
        } else if (rel.endsWith(TMP_SUFFIX)) {
            // Leftover from an interrupted atomic write. Reading never mutates
            // the output directory, so these are skipped rather than removed.
            continue;
        } else {
            out.push(rel);
        }
    }
    return out;
}

function hashFile(file: string): string {
    try {
        return hashText(readFileSync(file, "utf8"));
    } catch (error) {
        throw generateError(
            "dejavu.generate.read-failed",
            `cannot read generated file ${file}: ${errorText(error)}`,
            file,
        );
    }
}

// ---------------------------------------------------------------------------
// Template scanning
// ---------------------------------------------------------------------------

function scanRoot(rootDir: string, extensions: string[]): string[] {
    const out: string[] = [];
    walk(rootDir, "", 0);
    out.sort(compare);
    return out;

    function walk(dir: string, prefix: string, depth: number): void {
        if (depth > 64) {
            throw generateError(
                "dejavu.generate.depth-exceeded",
                `template root ${rootDir} exceeds the 64-level scan limit`,
                dir,
                "load",
            );
        }
        const entries = readdirSync(dir, { withFileTypes: true }).sort((a, b) => compare(a.name, b.name));
        for (const entry of entries) {
            const abs = join(dir, entry.name);
            const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
            if (entry.isSymbolicLink()) {
                throw generateError(
                    "dejavu.generate.symlink-not-supported",
                    `symbolic links are not supported in template roots: ${abs}`,
                    abs,
                    "load",
                );
            }
            if (entry.isDirectory()) {
                if (entry.name === ".git" || entry.name === "node_modules") continue;
                walk(abs, rel, depth + 1);
                continue;
            }
            if (!entry.isFile()) continue;
            if (admits(entry.name, extensions)) out.push(rel);
        }
    }
}

function admits(name: string, extensions: string[]): boolean {
    for (const extension of extensions) {
        if (extension === "") {
            if (!name.includes(".")) return true;
            continue;
        }
        if (name.endsWith(extension)) return true;
    }
    return false;
}

// ---------------------------------------------------------------------------
// Config import dependencies (watch mode)
// ---------------------------------------------------------------------------

function configDependencies(file: string): string[] {
    const found = new Set<string>();
    visit(file, 0);

    function visit(current: string, depth: number): void {
        if (depth > 16 || found.has(current)) return;
        found.add(current);
        let source: string;
        try {
            source = readFileText(current);
        } catch {
            return;
        }
        const pattern = /\b(?:import|export)\s+(?:[^;'"]*?\s+from\s+)?["'](\.[^"']+)["']/g;
        for (const match of source.matchAll(pattern)) {
            const specifier = match[1];
            if (!specifier) continue;
            const base = resolve(dirname(current), specifier);
            for (const candidate of [
                base,
                `${base}.ts`,
                `${base}.mts`,
                `${base}.js`,
                `${base}.mjs`,
                join(base, "index.ts"),
                join(base, "index.js"),
            ]) {
                if (isFile(candidate)) {
                    visit(candidate, depth + 1);
                    break;
                }
            }
        }
    }

    found.delete(file);
    return [...found].sort(compare);
}

function safeResolveConfigPath(options: BuildGenerateOptions): string | undefined {
    try {
        return resolveConfigPath(options);
    } catch {
        return undefined;
    }
}

function listDirectories(root: string): string[] {
    const out = [root];
    try {
        for (const entry of readdirSync(root, { withFileTypes: true })) {
            if (!entry.isDirectory()) continue;
            if (entry.name === ".git" || entry.name === "node_modules") continue;
            out.push(...listDirectories(join(root, entry.name)));
        }
    } catch {
        // ignore unreadable directories
    }
    return out;
}

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

function generateError(
    code: string,
    message: string,
    path?: string,
    stage = "config",
): DejavuError {
    return new DejavuError({
        code,
        severity: "error",
        stage,
        message,
        ...(path ? { path } : {}),
        argsJson: "{}",
        related: [],
    });
}

function assertEntryExists(catalog: Catalog, name: string, reference: string): void {
    const colon = reference.indexOf(":");
    const rootName = colon > 0 ? reference.slice(0, colon) : "";
    const templatePath = colon > 0 ? reference.slice(colon + 1) : "";
    const root = catalog.roots.find((candidate) => candidate.name === rootName);
    if (!root) {
        throw generateError(
            "dejavu.generate.entry-not-found",
            `entry ${JSON.stringify(name)} references unknown root ${JSON.stringify(rootName)}`,
        );
    }
    if (!Object.prototype.hasOwnProperty.call(root.files, templatePath)) {
        throw generateError(
            "dejavu.generate.entry-not-found",
            `entry ${JSON.stringify(name)} references missing template ${JSON.stringify(reference)}`,
        );
    }
}

function assertSafeOutputPath(path: string): void {
    if (path === "" || path.startsWith("/") || /^[A-Za-z]:/.test(path) || path.split("/").some((s) => s === ".." || s === ".")) {
        throw generateError(
            "dejavu.generate.unsafe-path",
            `codegen produced an unsafe output path ${JSON.stringify(path)}`,
            undefined,
            "compile",
        );
    }
}

function relativePosix(from: string, to: string): string {
    const rel = relative(from, to).split(sep).join("/");
    return rel === "" ? "." : rel;
}

function displayPath(path: string, cwd: string): string {
    const rel = relativePosix(cwd, path);
    return rel === "." ? "." : rel;
}

function hashText(text: string): string {
    return `sha256:${createHash("sha256").update(text, "utf8").digest("hex")}`;
}

function readFileText(file: string): string {
    return readFileSync(file, "utf8");
}

/** Every file under `root` as a POSIX-relative path; a missing root yields none. */
function listRelativeFiles(root: string, prefix = ""): string[] {
    const out: string[] = [];
    if (!existsSync(root)) return out;
    for (const entry of readdirSync(root, { withFileTypes: true }).sort((a, b) => compare(a.name, b.name))) {
        const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
        if (entry.isDirectory()) {
            out.push(...listRelativeFiles(join(root, entry.name), rel));
        } else if (entry.isFile()) {
            out.push(rel);
        }
    }
    return out;
}

let generatorVersionCache: string | undefined;

/** Package version recorded in lock and transaction records (informational). */
function generatorVersion(): string {
    if (generatorVersionCache === undefined) {
        try {
            const root = join(dirname(fileURLToPath(import.meta.url)), "..");
            const meta = JSON.parse(readFileSync(join(root, "package.json"), "utf8")) as {
                version?: unknown;
            };
            generatorVersionCache = typeof meta.version === "string" ? meta.version : "unknown";
        } catch {
            generatorVersionCache = "unknown";
        }
    }
    return generatorVersionCache;
}

function errnoCode(error: unknown): string | undefined {
    if (!error || typeof error !== "object") return undefined;
    const code = (error as { code?: unknown }).code;
    return typeof code === "string" ? code : undefined;
}

function errorText(error: unknown): string {
    return error instanceof Error ? error.message : String(error);
}

function asRecord(value: unknown): Record<string, unknown> | undefined {
    if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
    return value as Record<string, unknown>;
}

function compare(a: string, b: string): number {
    return a < b ? -1 : a > b ? 1 : 0;
}

function isFile(path: string): boolean {
    try {
        return statSync(path).isFile();
    } catch {
        return false;
    }
}

function isDirectory(path: string): boolean {
    try {
        return statSync(path).isDirectory();
    } catch {
        return false;
    }
}
